const sellers = [
  { slug: 'demo-supply-co', name: 'Demo Supply Co. (synthetic)', latency: [120, 380], failureRate: 0, accuracy: 0.95, factor: 0.45 },
  { slug: 'demo-gpu-cloud', name: 'Demo GPU Cloud (synthetic)', latency: [80, 260], failureRate: 0.02, accuracy: 0.85, factor: 0.6 },
  { slug: 'demo-edge-labs', name: 'Demo Edge Labs (synthetic)', latency: [250, 900], failureRate: 0.06, accuracy: 0.7, factor: 0.35 },
];

const usd = (v: number) => Math.round(v * 1_000_000);

export async function seedCatalog() {
  for (const p of providers) await prisma.provider.upsert({ where: { id: p.id }, create: p, update: p });
  for (const m of models) {
    const data = {
      name: m.name,
      providerId: m.providerId,
      family: m.family,
      description: m.description,
      contextWindow: m.contextWindow,
      maxOutputTokens: m.maxOutputTokens,
      inputModalities: m.input,
      outputModalities: m.output,
      apiSupported: m.apiSupported ?? true,
      baselineInputPrice: m.price ? usd(m.price[0]) : null,
      baselineOutputPrice: m.price ? usd(m.price[1]) : null,
      baselinePriceSource: m.price ? DEMO_PRICE_NOTE : null,
      baselinePriceIsDemo: true,
      isDemo: true,
      aliases: m.aliases ?? [],
    };
    await prisma.model.upsert({ where: { id: m.id }, create: { id: m.id, ...data }, update: data });
    for (const cap of m.caps) {
      await prisma.modelCapability.upsert({
        where: { modelId_capability: { modelId: m.id, capability: cap } },
        create: { modelId: m.id, capability: cap, status: 'declared', source: DECLARED },
        update: {},
      });
    }
  }
  console.log(`[ok] Catalog: ${providers.length} providers, ${models.length} models (demo reference prices)`);
}

export async function seedSellers() {
  if (!env.DEMO_MODE) {
    console.log('- DEMO_MODE=false - skipping demo sellers');
    return;
  }
  const chatModels = models.filter((m) => m.apiSupported !== false);
  for (const [si, s] of sellers.entries()) {
    let org = await prisma.organization.findUnique({ where: { slug: s.slug } });
    if (org) continue;
    org = await prisma.organization.create({ data: { name: s.name, slug: s.slug, isDemo: true } });
    const endpoint = await prisma.sellerEndpoint.create({
      data: {
        orgId: org.id,
        name: `${s.name} endpoint`,
        adapter: 'demo',
        baseUrl: 'demo://synthetic',
        config: { models: chatModels.map((m) => m.id), latencyMs: s.latency, failureRate: s.failureRate, arithmeticAccuracy: s.accuracy },
      },
    });
    await verifyEndpoint(endpoint.id);
    for (const [mi, m] of chatModels.entries()) {
      if ((mi + si) % 3 === 2) continue; // not every seller offers every model
      const factor = s.factor + ((mi * 7 + si * 3) % 10) / 100;
      const inputPrice = usd(m.price![0] * factor);
      const outputPrice = usd(m.price![1] * factor);
      const offer = await prisma.offer.create({
        data: {
          sellerOrgId: org.id,
          endpointId: endpoint.id,
          modelId: m.id,
          upstreamModel: m.id,
          inputPrice,
          outputPrice,
          isDemo: true,
          maxConcurrency: 16,
          rpmLimit: 600,
          timeoutMs: 15_000,
        },
      });
      // Illustrative demo price history over the last 30 days.
      for (const [daysAgo, drift] of [
        [28, 1.18],
        [18, 1.08],
        [9, 1.03],
        [0, 1],
      ] as const) {
        await prisma.offerPriceHistory.create({
          data: { offerId: offer.id, modelId: m.id, inputPrice: Math.round(inputPrice * drift), outputPrice: Math.round(outputPrice * drift), recordedAt: new Date(Date.now() - daysAgo * 86_400_000) },
        });
      }
      const result = await validateOffer(offer.id);
      if (result.ok) await prisma.offer.update({ where: { id: offer.id }, data: { status: 'ACTIVE' } });
    }
  }
  const active = await prisma.offer.count({ where: { status: 'ACTIVE', isDemo: true } });
  console.log(`[ok] Demo sellers: ${sellers.length} synthetic sellers, ${active} validated demo offers`);
}

const DEMO_EMAIL = 'demo@nexovra.local';
const DEMO_PASSWORD = 'demo-password-123';

export async function seedDemoBuyer() {
  if (!env.DEMO_MODE) return null;
  let user = await prisma.user.findUnique({ where: { email: DEMO_EMAIL } });
  if (!user) user = await createUserWithWorkspace({ email: DEMO_EMAIL, name: 'Demo Builder', passwordHash: await hashPassword(DEMO_PASSWORD), emailVerified: true });
  const membership = await prisma.membership.findFirstOrThrow({ where: { userId: user.id, org: { personal: true } } });
  await creditBalance({ orgId: membership.orgId, amountMicros: 25_000_000n, type: 'DEMO_CREDIT', paymentRef: 'seed-demo-buyer', description: 'Demo credit (not real money) from seed script' });
  console.log(`[ok] Demo buyer: ${DEMO_EMAIL} / ${DEMO_PASSWORD}  (demo mode only)`);
  return membership.orgId;
}

export async function seedTraffic(orgId: string) {
  const existing = await prisma.inferenceRequest.count({ where: { orgId, source: 'SEED' } });
  if (existing) {
    console.log('- Demo traffic already present - skipping');
    return;
  }
  const chatModels = models.filter((m) => m.apiSupported !== false).map((m) => m.id);
  const prompts = ['Summarize the benefits of unit tests in two sentences.', 'Write a haiku about latency.', 'What is 17 + 25?', 'Give three names for a coffee shop.', 'Explain what an API key is.'];
  const jobs = Array.from({ length: 120 }, (_, i) => ({ model: chatModels[(i * 5) % chatModels.length]!, prompt: prompts[i % prompts.length]!, mode: (['LOWEST_COST', 'BALANCED', 'LOWEST_COST', 'QUALITY_FIRST'] as const)[i % 4] }));
  let done = 0;
  const worker = async () => {
    for (;;) {
      const job = jobs.shift();
      if (!job) return;
      try {
        await runChatCompletion({ orgId, source: 'SEED' }, { model: job.model, messages: [{ role: 'user', content: job.prompt }], max_tokens: 200, nexovra: { routing_mode: job.mode } });
      } catch {
        /* failures are recorded in the request log */
      }
      done++;
    }
  };
  await Promise.all(Array.from({ length: 6 }, worker));
  // Spread the generated demo requests across the last 14 days so charts have shape. They remain flagged isDemo/SEED.
  await prisma.$executeRaw`
    UPDATE "InferenceRequest" SET "createdAt" = "createdAt" - (random() * interval '14 days')
    WHERE "orgId" = ${orgId} AND source = 'SEED'`;
  await prisma.$executeRaw`
    UPDATE "RequestAttempt" a SET "createdAt" = r."createdAt" FROM "InferenceRequest" r WHERE a."requestId" = r.id AND r.source = 'SEED'`;
  await prisma.$executeRaw`
    UPDATE "BillingTransaction" t SET "createdAt" = r."createdAt" FROM "InferenceRequest" r WHERE t."requestId" = r.id AND r.source = 'SEED'`;
  await prisma.usageRecord.deleteMany({ where: { orgId } });
  await prisma.$executeRaw`
    INSERT INTO "UsageRecord" (id, "orgId", "apiKeyId", "modelId", day, "keyScope", requests, failures, "inputTokens", "outputTokens", "costMicros", "baselineCostMicros")
    SELECT md5(random()::text || "modelId" || date_trunc('day', "createdAt")::text), "orgId", NULL, "modelId", date_trunc('day', "createdAt")::date, 'dashboard',
      COUNT(*)::int, COUNT(*) FILTER (WHERE status = 'FAILED')::int, SUM("inputTokens")::bigint, SUM("outputTokens")::bigint,
      SUM("costMicros")::bigint, COALESCE(SUM("baselineCostMicros"), 0)::bigint
    FROM "InferenceRequest" WHERE "orgId" = ${orgId} AND "modelId" IS NOT NULL AND status IN ('SUCCESS', 'FAILED')
    GROUP BY "orgId", "modelId", date_trunc('day', "createdAt")`;
  // Restore offers that failed during generation so the demo starts healthy (failures stay in the history).
  await prisma.offer.updateMany({ where: { isDemo: true, healthStatus: 'UNHEALTHY' }, data: { healthStatus: 'HEALTHY', unhealthyUntil: null } });
  console.log(`[ok] Demo traffic: ${done} requests sent through the real pipeline against demo offers`);
}

export async function seedBenchmarks() {
  const exists = await prisma.benchmarkResult.count({ where: { isPublic: true } });
  if (exists) return;
  let org = await prisma.organization.findUnique({ where: { slug: 'nexovra-benchmarks-demo' } });
  org ??= await prisma.organization.create({ data: { name: 'Nexovra Benchmarks (demo)', slug: 'nexovra-benchmarks-demo', isDemo: true } });
  await creditBalance({ orgId: org.id, amountMicros: 10_000_000n, type: 'DEMO_CREDIT', paymentRef: 'seed-benchmarks', description: 'Demo credit for benchmark runs' });
  const ids = ['llama-3.1-8b-instruct', 'llama-3.3-70b-instruct', 'qwen-2.5-72b-instruct', 'deepseek-v3', 'mistral-7b-instruct-v0.3'];
  for (const modelId of ids) await runArithmeticBenchmark({ orgId: org.id, modelId, isPublic: true });
  console.log(`[ok] Demo benchmarks: ran nexovra-arith-smoke against ${ids.length} models on demo endpoints (synthetic results)`);
}
